import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useTranslation } from 'react-i18next';
import {
  Container,
  Paper,
  Typography,
  Button,
  Box,
  CircularProgress,
  Autocomplete,
  TextField
} from '@mui/material';
import MyLocationIcon from '@mui/icons-material/MyLocation';

const DistrictSelector = () => {
  const { t } = useTranslation();
  const navigate = useNavigate();
  const [loading, setLoading] = useState(false);
  const [state, setState] = useState('');
  const [district, setDistrict] = useState('');
  const [states, setStates] = useState([]);
  const [districts, setDistricts] = useState([]);
  const [loadingStates, setLoadingStates] = useState(false);
  const [loadingDistricts, setLoadingDistricts] = useState(false);

  useEffect(() => {
    // Fetch list of states on mount
    const loadStates = async () => {
      setLoadingStates(true);
      try {
        const res = await fetch('http://localhost:5001/api/districts/states');
        const list = await res.json();
        setStates(list || []);
      } catch (err) {
        console.error('Error loading states:', err);
      } finally {
        setLoadingStates(false);
      }
    };

    loadStates();
  }, []);

  useEffect(() => {
    // Fetch districts when state changes
    if (!state) {
      setDistricts([]);
      return;
    }

    const loadDistricts = async () => {
      setLoadingDistricts(true);
      try {
        const res = await fetch(`http://localhost:5001/api/districts/states/${encodeURIComponent(state)}/districts`);
        const list = await res.json();
        setDistricts(list || []);
      } catch (err) {
        console.error('Error loading districts:', err);
      } finally {
        setLoadingDistricts(false);
      }
    };

    loadDistricts();
  }, [state]);

  const detectLocation = async () => {
    setLoading(true);
    try {
      if ('geolocation' in navigator) {
        navigator.geolocation.getCurrentPosition(async (position) => {
          try {
            const { latitude, longitude } = position.coords;
            
            // Call backend reverse geocoding endpoint that matches to our database
            const response = await fetch('http://127.0.0.1:5001/api/districts/reverse-geocode', {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({ latitude, longitude })
            });

            if (!response.ok) {
              const errorData = await response.json();
              throw new Error(errorData.error || 'Failed to detect location from coordinates');
            }

            const data = await response.json();
            setState(data.state);
            setDistrict(data.district);
          } catch (err) {
            console.error('Error reverse geocoding:', err);
            alert(`Could not detect location: ${err.message}. Please select manually.`);
          } finally {
            setLoading(false);
          }
        }, (error) => {
          console.error('Geolocation error:', error);
          let errorMessage = 'Could not access your location. ';
          switch (error.code) {
            case error.PERMISSION_DENIED:
              errorMessage += 'Permission denied. Please enable location services.';
              break;
            case error.POSITION_UNAVAILABLE:
              errorMessage += 'Location information is unavailable.';
              break;
            case error.TIMEOUT:
              errorMessage += 'The request to get user location timed out.';
              break;
            default:
              errorMessage += 'An unknown error occurred.';
          }
          alert(errorMessage);
          setLoading(false);
        });
      } else {
        alert('Location detection is not supported by your browser');
        setLoading(false);
      }
    } catch (error) {
      console.error('Error in location detection:', error);
      alert('An error occurred during location detection. Please select manually.');
      setLoading(false);
    }
  };

  const handleSubmit = () => {
    if (state && district) {
      navigate(`/dashboard/${state}/${district}`);
    }
  };

  return (
    <Container maxWidth="sm" sx={{ mt: 4 }}>
      <Paper elevation={3} sx={{ p: 4 }}>
        <Typography variant="h4" component="h1" gutterBottom align="center">
          {t('dashboard.title')}
        </Typography>

        <Box sx={{ my: 3 }}>
          <Button
            fullWidth
            variant="outlined"
            startIcon={<MyLocationIcon />}
            onClick={detectLocation}
            disabled={loading}
          >
            {loading ? (
              <CircularProgress size={24} />
            ) : (
              t('location.detect')
            )}
          </Button>
        </Box>

        <Box sx={{ mb: 2 }}>
          <Typography variant="subtitle1" gutterBottom>
            {t('select.state')}
          </Typography>
          <Autocomplete
            options={states}
            value={state || null}
            onChange={(event, newValue) => {
              setState(newValue || '');
              setDistrict('');
            }}
            disabled={loadingStates}
            loading={loadingStates}
            renderInput={(params) => (
              <TextField
                {...params}
                placeholder="Search and select state..."
              />
            )}
            noOptionsText="No states available"
            loadingText="Loading states..."
            isOptionEqualToValue={(option, value) => option === value}
            getOptionLabel={(option) => option}
            filterOptions={(options, state) =>
              options.filter((option) =>
                option.toLowerCase().includes(state.inputValue.toLowerCase())
              )
            }
          />
        </Box>

        <Box sx={{ mb: 3 }}>
          <Typography variant="subtitle1" gutterBottom>
            {t('select.district')}
          </Typography>
          <Autocomplete
            options={districts}
            value={district || null}
            onChange={(event, newValue) => {
              setDistrict(newValue || '');
            }}
            disabled={!state || loadingDistricts}
            loading={loadingDistricts}
            renderInput={(params) => (
              <TextField
                {...params}
                placeholder="Search and select district..."
              />
            )}
            noOptionsText="No districts available"
            loadingText="Loading districts..."
            isOptionEqualToValue={(option, value) => option === value}
            getOptionLabel={(option) => option}
            filterOptions={(options, state) =>
              options.filter((option) =>
                option.toLowerCase().includes(state.inputValue.toLowerCase())
              )
            }
          />
        </Box>

        <Button
          fullWidth
          variant="contained"
          size="large"
          onClick={handleSubmit}
          disabled={!state || !district}
        >
          View Dashboard
        </Button>
      </Paper>
    </Container>
  );
};

export default DistrictSelector;